//! Windows IP Helper boundary. Never enables weak-host routing or forwarding.
use std::{io, net::Ipv4Addr};
use windows_sys::Win32::{
    NetworkManagement::{IpHelper::*, Ndis::IfOperStatusUp},
    Networking::WinSock::{AF_INET, IpDadStatePreferred, SOCKADDR_INET},
};

fn status(code: u32) -> io::Result<()> {
    if code == 0 {
        Ok(())
    } else {
        Err(io::Error::from_raw_os_error(code as i32))
    }
}

fn interface_row(name: &str) -> io::Result<MIB_IF_ROW2> {
    // Names are generated by the shared configuration converter, not supplied
    // by callers as arbitrary system interface selectors.
    if name.len() != 12
        || !name.starts_with("rove")
        || !name[4..].bytes().all(|b| b.is_ascii_hexdigit())
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Invalid Rove interface alias",
        ));
    }
    let expected_description = format!("{name} Tunnel").to_ascii_lowercase();
    let name: Vec<u16> = name.encode_utf16().chain(Some(0)).collect();
    let mut row = MIB_IF_ROW2::default();
    // SAFETY: live NUL-terminated alias and writable initialized API structure.
    unsafe {
        status(ConvertInterfaceAliasToLuid(
            name.as_ptr(),
            &mut row.InterfaceLuid,
        ))?;
        status(GetIfEntry2(&mut row))?;
    }
    let end = row
        .Description
        .iter()
        .position(|c| *c == 0)
        .unwrap_or(row.Description.len());
    let description = String::from_utf16_lossy(&row.Description[..end]).to_ascii_lowercase();
    if row.OperStatus != IfOperStatusUp
        || row.Type != IF_TYPE_PROP_VIRTUAL
        || !(description.contains("wintun")
            || description.contains("easytier")
            || description == expected_description)
    {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            "Overlay requires an active EasyTier/Wintun interface",
        ));
    }
    Ok(row)
}

struct Table<T>(*mut T);
impl<T> Drop for Table<T> {
    fn drop(&mut self) {
        // SAFETY: all instances own a table allocated by an IP Helper API.
        unsafe { FreeMibTable(self.0.cast()) };
    }
}

fn ipv4(address: SOCKADDR_INET) -> Ipv4Addr {
    // SAFETY: callers only pass rows from an AF_INET table.
    Ipv4Addr::from(unsafe { address.Ipv4.sin_addr.S_un.S_addr }.to_ne_bytes())
}

fn require_strong_host(guarded_forwarding: bool) -> io::Result<()> {
    let mut ptr = std::ptr::null_mut();
    // SAFETY: API initializes ptr; owner remains alive through iteration.
    unsafe {
        status(GetIpInterfaceTable(AF_INET, &mut ptr))?;
        let table = Table(ptr);
        let rows =
            std::slice::from_raw_parts((*table.0).Table.as_ptr(), (*table.0).NumEntries as usize);
        if rows.iter().any(|row| {
            row.Connected
                && (row.WeakHostReceive
                    || row.WeakHostSend
                    || (row.ForwardingEnabled && !guarded_forwarding))
        }) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "Overlay isolation requires strong-host send/receive and disabled IP forwarding",
            ));
        }
    }
    Ok(())
}

pub(crate) fn validate_overlay(interface: &str, address: Ipv4Addr) -> anyhow::Result<u32> {
    let index = validate_overlay_facts(interface, address)?;
    require_strong_host(has_helper_isolation(index, address))?;
    Ok(index)
}

/// Helper-only preflight before installing WFP. Business listeners always use
/// validate_overlay, which additionally requires isolation.
pub(crate) fn validate_overlay_facts(interface: &str, address: Ipv4Addr) -> anyhow::Result<u32> {
    anyhow::ensure!(
        !address.is_unspecified()
            && !address.is_loopback()
            && !address.is_multicast()
            && !address.is_broadcast(),
        "Invalid overlay address"
    );
    let native = interface_row(interface)?;
    let mut ptr = std::ptr::null_mut();
    let mut found = false;
    // SAFETY: AF_INET table rows remain valid until the RAII owner is dropped.
    unsafe {
        status(GetUnicastIpAddressTable(AF_INET, &mut ptr))?;
        let table = Table(ptr);
        for row in
            std::slice::from_raw_parts((*table.0).Table.as_ptr(), (*table.0).NumEntries as usize)
        {
            let assigned = ipv4(row.Address);
            if row.InterfaceIndex == native.InterfaceIndex {
                found |= assigned == address && row.DadState == IpDadStatePreferred;
            } else if !assigned.is_loopback() {
                let subnet = ipnet::Ipv4Net::new(assigned, row.OnLinkPrefixLength)?;
                anyhow::ensure!(
                    !subnet.contains(&address),
                    "Overlay address overlaps another interface subnet"
                );
            }
        }
    }
    anyhow::ensure!(found, "Address is not assigned to the overlay interface");
    check_routes(native.InterfaceIndex, ipnet::Ipv4Net::new(address, 32)?)?;
    Ok(native.InterfaceIndex)
}

type Proofs = std::collections::BTreeMap<(uuid::Uuid, uuid::Uuid), (u32, Ipv4Addr, u32)>;
static HELPER_PROOFS: std::sync::OnceLock<std::sync::Mutex<Proofs>> = std::sync::OnceLock::new();

pub(crate) fn set_helper_isolation(
    session: uuid::Uuid,
    instance: uuid::Uuid,
    value: Option<(u32, Ipv4Addr, u32)>,
) {
    let mut proofs = HELPER_PROOFS.get_or_init(Default::default).lock().unwrap();
    if let Some(value) = value {
        proofs.insert((session, instance), value);
    } else {
        proofs.remove(&(session, instance));
    }
}

pub(crate) fn clear_helper_isolation(session: uuid::Uuid) {
    HELPER_PROOFS
        .get_or_init(Default::default)
        .lock()
        .unwrap()
        .retain(|(owner, _), _| *owner != session);
}

fn has_helper_isolation(index: u32, address: Ipv4Addr) -> bool {
    HELPER_PROOFS
        .get_or_init(Default::default)
        .lock()
        .unwrap()
        .values()
        .any(|&(i, a, pid)| {
            if i != index || a != address {
                return false;
            }
            matches!(helper_process_exited(pid), Ok(false))
        })
}

pub(crate) fn helper_process_exited(pid: u32) -> io::Result<bool> {
    use windows_sys::Win32::{
        Foundation::{CloseHandle, WAIT_OBJECT_0, WAIT_TIMEOUT},
        System::Threading::{OpenProcess, PROCESS_SYNCHRONIZE, WaitForSingleObject},
    };
    if pid == 0 {
        return Ok(true);
    }
    // Fresh handle, not a cached Boolean that survives helper termination.
    unsafe {
        let process = OpenProcess(PROCESS_SYNCHRONIZE, 0, pid);
        if process.is_null() {
            let error = io::Error::last_os_error();
            return if error.raw_os_error() == Some(87) {
                Ok(true)
            } else {
                Err(error)
            };
        }
        let state = WaitForSingleObject(process, 0);
        CloseHandle(process);
        match state {
            WAIT_OBJECT_0 => Ok(true),
            WAIT_TIMEOUT => Ok(false),
            _ => Err(io::Error::last_os_error()),
        }
    }
}

fn check_routes(index: u32, subnet: ipnet::Ipv4Net) -> io::Result<()> {
    let mut ptr = std::ptr::null_mut();
    // SAFETY: AF_INET table allocation and all its rows remain owned here.
    unsafe {
        status(GetIpForwardTable2(AF_INET, &mut ptr))?;
        let table = Table(ptr);
        for row in
            std::slice::from_raw_parts((*table.0).Table.as_ptr(), (*table.0).NumEntries as usize)
        {
            if row.InterfaceIndex == index
                || row.DestinationPrefix.PrefixLength == 0
                || row.Loopback
            {
                continue;
            }
            let other = ipnet::Ipv4Net::new(
                ipv4(row.DestinationPrefix.Prefix),
                row.DestinationPrefix.PrefixLength,
            )
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
            if other.contains(&subnet.network()) || subnet.contains(&other.network()) {
                return Err(io::Error::new(
                    io::ErrorKind::AddrInUse,
                    "Overlay subnet overlaps another interface route",
                ));
            }
        }
    }
    Ok(())
}

pub(crate) fn check_requested_subnet(subnet: ipnet::Ipv4Net) -> io::Result<()> {
    check_routes(0, subnet)
}

#[cfg(feature = "easytier")]
pub(crate) fn check_overlay_subnet(interface: &str, subnet: ipnet::Ipv4Net) -> io::Result<()> {
    check_routes(interface_row(interface)?.InterfaceIndex, subnet)
}

pub(crate) fn bind_overlay(
    interface: &str,
    address: std::net::SocketAddrV4,
) -> anyhow::Result<tokio::net::TcpListener> {
    validate_overlay(interface, *address.ip())?;
    // Windows strong-host receive rejects packets arriving on another NIC for
    // this exact address. Never bind a wildcard or modify the host routing mode.
    let socket = tokio::net::TcpSocket::new_v4()?;
    socket.bind(address.into())?;
    Ok(socket.listen(128)?)
}
